export const pair=(en,zh)=>({en,zh});
const section=(title,zhTitle,text,zhText)=>({title:pair(title,zhTitle),text:pair(text,zhText)});
const question=(q,zq,a,za)=>({q:pair(q,zq),a:pair(a,za)});
const sharedQuestions=[
 question('What should I include in a custom drinkware enquiry?','定制询价需要提供哪些资料？','Send a model or reference, intended use, estimated quantity, artwork, packing, destination and required arrival date. If a specification is undecided, describe the use so it can be reviewed with the model.','提供型号或参考、用途、预计数量、图稿、包装、交货地和到货日期。参数未确定时，可先描述用途，再按型号核对。'),
 question('Are the reference images and specifications the final order?','参考图片和参数就是最终订单吗？','Use the references to discuss the project. Confirm the final material, dimensions, components, artwork and sample in the written specification before production. AI artwork previews are identified on the model pages.','参考资料用于沟通项目。生产前应在书面规格中确认材质、尺寸、组成、图稿和样品；型号页已标识 AI 图案预览。'),
 question('How is a quote request sent?','询价会怎样发送？','Submit the project details and artwork on the contact page. The receiving service confirms storage with an enquiry reference. Email forwarding is pending configuration in this preview; website receipt does not mean an email has been delivered.','在联系页填写项目需求并上传图稿，接收服务确认保存后会显示询盘编号。当前预览的邮件转送尚未配置；网站接收成功不代表邮件已送达。')
];
const commonRows=[
 [pair('Model & intended use','型号与用途'),pair('Choose the product format, serving use and required accessories.','选择器型、使用方式和所需配件。')],
 [pair('Logo & sample','Logo 与样品'),pair('Agree the artwork, decoration position and approval sample for the selected model.','按型号确认图稿、装饰位置和审核样品。')],
 [pair('Order & delivery','订单与交付'),pair('Confirm quantity, packing, price, minimum order, schedule and shipping scope in the quote.','在报价中确认数量、包装、价格、起订量、排期和运输范围。')]
];
function spec(route,title,zhTitle,lead,zhLead,extras={}){return{route,title:pair(title,zhTitle),lead:pair(lead,zhLead),kicker:pair('PROCUREMENT / CUSTOMBYF','采购指南 / CUSTOMBYF'),sections:[],rows:commonRows,faqs:sharedQuestions,models:['BSB-001','BD-001','FGB-034'],related:['/products/','/faq/','/contact/'],...extras};}
export const pages=[
 spec('/low-moq-custom-cups/','Custom Cups with Low MOQ: Plan a Small-Batch Enquiry','低起订定制杯：准备小批量采购需求','Planning low MOQ custom cups starts with the model, decoration and quantity per design. Share the batch you need so the minimum order and sample options can be reviewed for that specification.','小批量定制杯应先明确型号、工艺和每款数量。提供计划采购量，便于按具体规格评估起订量与样品方案。',{
  sections:[section('What affects the minimum order?','哪些因素影响起订量？','An existing shape, a new body colour, multiple logo versions and custom packaging are different production briefs. List quantities per model, colour and artwork rather than only the total order.','现有器型、新杯身颜色、多版 Logo 和定制包装对应不同生产需求。请分别列出每个型号、颜色和图稿的数量。'),section('Compare the same specification','用相同规格比较方案','For a small run, compare a simpler logo treatment, standard components and the packaging you actually need. Ask for separate sample and production quotes so the two costs are clear.','小批量项目可比较较简单的 Logo 方案、标准组件与实际需要的包装。样品和量产分别报价，便于了解各自费用。')],
  faqs:[question('What is the minimum order quantity for custom cups?','定制杯的起订量是多少？','MOQ is quoted for the selected model, decoration, colour and packing. There is no confirmed site-wide minimum. Send the quantity you need, including quantities per design, for a project review.','起订量按型号、工艺、颜色和包装报价，目前没有已确认的全站统一数值。请提供总量及每版图案数量进行评估。'),...sharedQuestions],related:['/wholesale/','/free-samples/','/collapsible-cups/','/contact/']
 }),
 spec('/free-samples/','Custom Drinkware Samples & Logo Proofs','定制杯样品与 Logo 审核','Use a sample to review the selected shape, material, artwork and accessories before committing to a production specification. Request the sample type you need and confirm its cost and shipping arrangements.','通过样品核对器型、材料、图稿和配件，再确认量产规格。申请时说明需要哪种样品，并确认费用及运输安排。',{
  rows:[[pair('Reference sample','参考样'),pair('Review an existing product format and identify what would change for your project.','查看现有器型，并明确项目需要调整的内容。')],[pair('Decorated approval sample','装饰确认样'),pair('Review your artwork, print position and selected finish on the agreed model.','在约定型号上审核图稿、印刷位置和外观。')],[pair('New development sample','开发样'),pair('Discuss the structure, tooling scope and review criteria for a new design.','新设计需讨论结构、模具范围与审核标准。')]],
  sections:[section('Define what the sample must answer','明确样品要解决的问题','For a cup, consider handling, serving capacity, lid fit and logo position. For LED products, include lighting, activation and cleaning instructions. A reference sample does not establish the final order configuration.','杯具样品可核对手感、使用容量、杯盖配合和 Logo 位置；LED 产品还需核对灯效、触发和清洁说明。参考样不等于最终订单配置。'),section('Record the approval','记录确认结果','Keep the model, artwork version, changes requested and acceptance points together. Confirm whether the sample is for appearance, fit, function or production approval before relying on it.','把型号、图稿版本、修改内容和验收点一起记录，明确样品用于外观、装配、功能还是量产确认。')],
  faqs:[question('Can I get a free sample before ordering?','下单前可以获得免费样品吗？','Sample availability, charges, artwork work, dispatch and freight are confirmed for the chosen request. This page does not promise a free kit, a fixed dispatch time or an automatic credit against an order.','样品供应、费用、图稿工作、发样时间和运费按具体申请确认。本页不承诺免费套装、固定发样时间或自动抵扣订单费用。'),...sharedQuestions],related:['/low-moq-custom-cups/','/custom-led-drinkware/','/contact/']
 }),
 spec('/rush-production/','Rush Custom Cups: Review Your Required Arrival Date','加急定制杯：评估所需到货日期','For rush custom cups, start with the required arrival date and destination. The model, artwork approval, production readiness and shipping route must be reviewed together before a schedule can be confirmed.','加急定制杯应从所需到货日与交货地开始，结合型号、图稿确认、生产准备及运输路线，评估可行排期。',{
  rows:[[pair('Required arrival','所需到货'),pair('Country, postcode, event date and the latest usable arrival date.','国家、邮编、活动日及最晚可接受到货日。')],[pair('Ready to approve','确认准备'),pair('Model, quantities, artwork, accessories and packaging decisions.','型号、数量、图稿、配件与包装的确认情况。')],[pair('Quoted schedule','报价排期'),pair('Separate sample approval, production, dispatch and transit assumptions.','分别说明样品确认、生产、出货和运输的条件。')]],
  sections:[section('Work back from the event','从活动日期倒排','Identify which choices are flexible: model, artwork complexity, packing or delivery location. A simpler approved specification may be easier to review than a new structure, but availability must still be confirmed.','明确可调整的型号、图稿复杂度、包装或交货地。相较新结构，较简单且已确认的规格更便于评估，但仍需核实生产条件。'),section('Approval before a commitment','确认后再约定','Agree the specification and a written schedule before treating an event date as achievable. Production time is different from transit time; the quote should state both scopes and relevant assumptions.','在确认规格与书面排期后，再判断能否赶上活动。生产时间与运输时间不同，报价应分别说明范围与条件。')],
  faqs:[question('How fast can custom cups be produced?','定制杯最快多久可以生产？','There is no universal rush lead time across plastic, silicone and LED models. Send the chosen models, quantities, artwork status and arrival date. The team will review the production and delivery plan for that request.','塑料、硅胶和 LED 型号没有统一加急交期。请提供型号、数量、图稿状态和到货日，按该项目评估生产与交付方案。'),...sharedQuestions],related:['/free-samples/','/wholesale/','/contact/']
 }),
 spec('/case-studies/','Custom Drinkware Applications & Project Planning','定制杯应用与项目规划','Explore buying briefs for events, distributors and hospitality projects. These application plans show what to specify and compare; they are not presented as completed customer orders or testimonials.','查看活动、经销与餐饮项目的采购方案，了解应确认和比较的内容。以下为应用规划，不作为已完成客户订单或评价展示。',{
  sections:[section('Wedding and celebration drinkware','婚礼与庆祝活动','Start with the serving format and venue rules. Compare cup shapes, names or dates in the artwork, quantities per design and individual versus bulk packing. Use the same approved artwork across matching accessories where suitable.','从饮品形式与场地方规则开始，比较杯型、姓名日期图稿、每版数量以及独立或批量包装，并评估配件能否使用同一套图稿。'),section('Distributor and repeat-order programmes','经销与复购项目','Create a model shortlist with artwork versions, packaging requirements and delivery destinations. Confirm repeat-order specifications, documentation and commercial terms for the actual programme.','建立型号清单，记录图稿版本、包装和交货地，按实际项目确认复购规格、文件与商业条件。'),section('LED drinkware for venue projects','场馆 LED 酒具项目','Select cups, ice buckets or accessories by vessel and lighting needs. Review power, activation, logo visibility, cleaning instructions and packing as model-specific choices.','按器型与灯效选择杯具、冰桶或配件，并逐型号核对供电、触发、Logo 可见性、清洁说明和包装。')],related:['/wedding-cups/','/distributor-program/','/custom-led-drinkware/','/contact/']
 }),
 spec('/wholesale/','Wholesale Custom Drinkware: Models, Logo & Bulk Quotes','批发定制杯：型号、Logo 与批量报价','Compare wholesale custom drinkware by product format, material and branding requirements. A useful bulk quote records quantities per model, colour and artwork together with packaging and delivery scope.','批发定制杯应按器型、材料和品牌要求选款。批量报价需记录每款、每色、每版图稿数量，以及包装与交付范围。',{
  sections:[section('Compare like-for-like quotations','比较同口径报价','Check whether the price includes the same model, artwork, components and packing. Separate development, samples, decoration and shipping charges where relevant; a generic calculator cannot replace a model-specific quote.','核对各报价是否包含相同型号、图稿、配件与包装，并按需区分开发、样品、装饰和运输费用；通用计算器不能替代按型号报价。'),section('Plan a mixed product order','规划组合采购','List cup styles, coasters, openers and other accessories as separate line items. Confirm each component and its quantity before calling the combination a set.','将杯型、杯垫、开瓶器和其他配件分别列项，确认每件组成及数量后，再作为套装采购。')],related:['/products/','/custom-coasters/','/custom-bottle-openers/','/contact/']
 }),
 spec('/oem-manufacturer/','Custom Drinkware OEM & ODM Project Planning','定制杯 OEM／ODM 项目规划','深圳市宝源丰精密加工有限公司 focuses on silicone and plastic processing. Discuss CustomBYF drinkware and additional bar accessories through a model-based OEM or ODM brief, with specifications and supply arrangements agreed for the project.','深圳市宝源丰精密加工有限公司主营硅胶与塑胶加工。CustomBYF 杯具及补充酒具配件可按型号准备 OEM／ODM 需求，并逐项目确认规格与供货安排。',{
  sections:[section('Existing model or new structure?','现有型号还是新结构？','For an existing reference, identify the changes to colour, artwork, components or packing. For a new shape, send drawings, intended use and the fit requirements so tooling and sampling can be assessed.','现有参考款需说明颜色、图稿、组成和包装的变化；新外形请提供图纸、用途和配合要求，以评估模具及样品。'),section('Agree a production specification','确认生产规格','Record the selected materials, dimensions, decoration, acceptance points and required documents. Approval should identify the exact sample and artwork version used for the order.','记录材料、尺寸、装饰、验收点及所需文件。订单确认应明确采用的样品与图稿版本。')],related:['/factory/','/free-samples/','/custom-led-drinkware/','/contact/']
 }),
 spec('/distributor-program/','Custom Drinkware for Distributors & Resellers','经销商与转售商定制杯采购','Prepare a repeatable custom drinkware specification for distributor projects. Share the product shortlist, artwork versions, packing labels, order quantities and delivery scope to discuss the commercial arrangement.','为经销项目准备可复用的定制规格。提供型号清单、图稿版本、包装标签、数量与交货范围，以沟通具体合作条件。',{
  sections:[section('Keep repeat orders consistent','让复购需求清楚一致','Use a model and artwork register rather than relying on a photograph alone. Note approved colours, components, packaging and any changes requested for the next run.','用型号和图稿记录管理复购，明确已确认颜色、配件、包装和下次订单的变更，避免仅凭照片判断。'),section('Confirm the commercial scope','确认商业合作范围','Payment, packing, dispatch arrangements and any destination-specific preparation must be agreed in writing. No automatic credit terms, membership tier or shipping programme is promised here.','付款、包装、出货与目的地相关准备需书面约定。本页不承诺自动账期、会员等级或特定代发方案。')],related:['/wholesale/','/custom-coasters/','/custom-bottle-openers/','/contact/']
 }),
 spec('/cup-materials-guide/','Plastic & Silicone Cup Materials: A Model-Based Buying Guide','塑料与硅胶杯材料：按型号选型指南','Compare cup materials against the selected model and its intended use. Material names help define the discussion; they do not establish a universal temperature rating, food-contact claim or dishwasher instruction.','按具体型号和用途比较杯具材料。材料名称有助于选型，但不能据此推断统一耐温、食品接触合规或机洗要求。',{
  rows:[[pair('PP, PET, acrylic and other plastics','PP、PET、亚克力等塑料'),pair('Read the recorded material for the model; compare shape, lid fit, serving use and the required appearance.','查看型号已记录材料，并比较器型、杯盖配合、用途与外观需求。')],[pair('Silicone','硅胶'),pair('Review the structure and target dimensions. Collapsible capacity and folded dimensions are customized for the project.','核对结构与目标尺寸；折叠杯容量及折叠尺寸按项目定制。')],[pair('LED assemblies','LED 组件'),pair('Separate the vessel material from the lighting, power and cleaning requirements.','区分杯体材料、灯效、供电与清洁要求。')]],
  sections:[section('Request documents for the actual product','按实际产品申请文件','Identify the model, material, intended drink, use conditions and destination. Ask which documents apply to that scope. Certificate placeholder images are not certification or test evidence.','说明型号、材料、饮品、使用条件与目的地，申请适用文件；证书占位图不代表认证或测试证据。'),section('Approve the decorated product','审核装饰后的产品','A material name alone does not confirm decoration adhesion, cleaning performance or component fit. Agree a relevant sample and acceptance criteria for the selected construction.','材料名称本身不能证明装饰附着、清洁性能或配件适配。应按所选结构约定样品和验收标准。')],related:['/custom-plastic-cups/','/custom-silicone-cups/','/collapsible-cups/','/certificates/']
 }),
 spec('/blog/how-much-do-custom-cups-cost/','How Much Do Custom Cups Cost? Build a Comparable Quote','定制杯多少钱？如何准备可比较的报价','Custom cup pricing depends on the model, material, decoration, quantity, packing and delivery scope. Request a quote against a clear specification rather than treating a generic price range as a factory offer.','定制杯价格取决于型号、材料、工艺、数量、包装和交付范围。按清楚的规格申请报价，不能把通用价格区间当成工厂报价。',{
  sections:[section('Separate the cost items','区分费用项目','Ask whether the quote includes the cup and accessories, artwork work, decoration, samples, tooling, packing and freight. Identify any one-off work separately so future orders can be compared fairly.','确认报价是否包含杯具配件、图稿、装饰、样品、模具、包装和运费，并单独列明一次性工作，便于比较后续订单。'),section('Quantity is part of the specification','数量也是规格的一部分','State quantities per model, colour and artwork version. A total order spread across several designs is not the same production brief as one design at the same total quantity.','分别说明每款、每色和每版图稿数量。多款合计数量与单款同等总量并不是同一个生产需求。'),section('What to send for an accurate comparison','怎样得到可比较的报价','Use the same model references, logo files, packing brief, destination and arrival requirement for each quotation. Check the written inclusions and approval conditions before choosing on unit price alone.','各报价采用相同型号、Logo 文件、包装需求、交货地与到货要求。比较单价前先核对书面包含项与确认条件。')],related:['/wholesale/','/low-moq-custom-cups/','/free-samples/','/contact/']
 }),
 spec('/blog/led-drinkware-101/','How LED Drinkware Works: Lighting, Power & Model Selection','LED 发光酒具原理：灯效、供电与型号选择','LED drinkware combines a vessel or accessory with an electrical light source. Select the vessel, lighting behaviour and branding together; power, activation, cleaning and runtime must be reviewed for the chosen configuration.','LED 酒具把杯具或配件与电光源组合起来。器型、灯效和品牌图案应一起选定；供电、触发、清洁与续航需按具体配置核对。',{
  sections:[section('LED, UV-reactive and glow materials','区分 LED、UV 反应与夜光材料','LED products use an electrical light source. UV-reactive and glow-in-the-dark products work differently and should not be counted as LED models solely because their name includes glow or neon.','LED 产品使用电光源。UV 反应与夜光材料的工作方式不同，不能因为名称包含发光、荧光或霓虹就当作 LED 型号。'),section('Choose the lighting configuration','选择灯效配置','Describe the required colours, modes and activation preference. Discuss the module position, access to controls and the appearance with the light on and off. Not every feature is available on every model.','说明灯色、模式与触发偏好，讨论灯组位置、开关操作及亮灯和熄灯外观；各型号不一定具备同样功能。'),section('Review power and cleaning','核对供电与清洁','Request the power configuration and model-specific instructions. Do not infer a runtime, ingress rating, dishwasher suitability or battery replacement method from the photograph or vessel material.','申请具体供电配置与使用说明，不从照片或杯体材料推断续航、防护等级、机洗适用性或更换电池方式。')],models:['FGB-034','FGB-001','BD-003'],related:['/led-light-up-cups/','/custom-led-drinkware/','/custom-ice-buckets/','/contact/']
 }),
 spec('/blog/how-to-order-custom-cups-step-by-step/','How to Order Custom Cups: From Brief to Approval','如何定制定制杯：从需求到订单确认','Start a custom cup order with the intended use, model references and quantities. Confirm the specification, artwork, sample approach and delivery scope before production is scheduled.','从用途、型号参考和数量开始准备定制杯订单。生产排期前，确认规格、图稿、样品方案和交付范围。',{
  sections:[section('Choose and describe','选款与需求','Compare product formats and list the chosen models. Record the serving use, materials or dimensions you require, and which points still need help with selection.','比较器型并列出型号，记录用途、材料或尺寸要求，以及需要协助选型的事项。'),section('Review artwork and samples','审核图稿与样品','Send usable artwork and identify colours, placement and packaging. Agree which sample or proof is needed and record the approved version with any acceptance points.','提供可用图稿，明确颜色、位置与包装，约定样品或效果稿，并记录确认版本与验收点。'),section('Confirm the quotation','确认报价','Review quantities, price, minimums, inclusions, production and shipping scope in writing. The schedule should start from its agreed approval conditions, not a universal website promise.','书面确认数量、价格、起订量、包含项、生产及运输范围。排期应以约定确认条件为起点，而不是套用网站统一承诺。')],related:['/products/','/free-samples/','/wholesale/','/contact/']
 }),
 spec('/blog/screen-printing-vs-uv-printing-on-cups/','Screen Printing vs UV Printing on Cups: What to Compare','杯具丝印与 UV 印刷：如何比较','Compare screen printing and UV printing using the actual artwork, selected surface and required appearance. Request a process review and decorated sample instead of assuming one method always costs less or suits every cup.','根据实际图稿、所选表面和外观要求比较丝印与 UV 印刷。申请工艺评估和装饰样，不预设某工艺始终更便宜或适用于所有杯型。',{
  rows:[[pair('Artwork','图稿'),pair('Compare spot colours, fine text, gradients and photographic detail in the actual file.','根据实际文件比较专色、细字、渐变和照片细节。')],[pair('Surface & geometry','表面与器型'),pair('Review curvature, coating, access, usable print area and registration requirements.','核对曲面、涂层、操作空间、可用印刷区域和套位要求。')],[pair('Approval','样品确认'),pair('Use a decorated sample to agree appearance and the relevant acceptance checks.','用装饰样确认外观及适用验收项目。')]],sections:[section('Build a fair quotation brief','准备同口径工艺需求','Keep the model, artwork, quantity and packing the same when comparing methods. Ask which setup work and process checks are included. Do not use an unverified quantity threshold as a universal rule.','比较工艺时保持型号、图稿、数量和包装一致，并确认包含的准备工作和检查内容，不把未核实的数量门槛当成通用规律。')],related:['/screen-printing/','/uv-printing/','/heat-transfer-printing/','/contact/']
 }),
 spec('/blog/how-to-verify-a-cup-supplier/','How to Review a Custom Cup Supplier Before Ordering','下单前如何核对定制杯供应商','Match the supplier identity, product references, production scope and project documents before approving an order. Ask for evidence that applies to the actual model and transaction rather than relying on badges or general statements.','下单前核对供应商主体、产品参考、生产范围与项目文件。证据应适用于实际型号及交易，不能只依赖图标或笼统说明。',{
  sections:[section('Identity and supply scope','主体与供货范围','Check who will quote, contract and supply the order. Distinguish the website brand, product naming and factory operator, and ask which processing steps apply to the chosen model.','确认报价、签约和供货主体，区分网站品牌、产品命名与工厂主体，并核对所选型号涉及的加工环节。'),section('Documents and samples','文件与样品','Request relevant documents with the operator, model or material scope, date and issuing body. Review their validity through the issuer where possible. A placeholder image or unrelated report is not evidence for your order.','申请能识别主体、型号或材料范围、日期及出具方的文件，并尽可能向出具方核验；占位图或无关报告不能证明订单符合要求。'),section('Approval and handover','确认与交接','Use a written specification, approved artwork and sample record. Agree the acceptance points, packing, commercial terms and delivery responsibilities before the order is released.','保留书面规格、确认图稿和样品记录，并在订单执行前约定验收点、包装、商业条件与交付责任。')],related:['/factory/','/certificates/','/free-samples/','/contact/']
 }),
 spec('/catalog-download/','Custom Drinkware Model Catalogue & Shortlist','定制杯型号目录与选型清单','Browse the current model pages or prepare a tailored catalogue request. Include the product lines, intended use and required specifications so the shortlist can match your project.','浏览当前型号页，或准备针对项目的目录需求。说明产品系列、用途与规格要求，让选型清单更贴近项目。',{
  sections:[section('Use the current model library','使用当前型号库','The online product pages show the model references and available recorded information. Compare materials, formats and custom requirements there, then identify the models you want to discuss.','在线产品页展示型号与已有资料，可据此比较材料、器型及定制要求，再列出需要沟通的型号。'),section('Request a focused catalogue','申请有针对性的目录','Tell us which product lines you need and whether the brief concerns logos, dimensions, LED configuration or matching accessories. Use the contact page to submit the catalogue requirements and supporting artwork. The confirmation distinguishes website storage from email delivery.','说明所需系列，以及 Logo、尺寸、LED 配置或配套产品方面的重点。可在联系页提交目录需求与图稿，提交结果会区分网站保存状态与邮件送达状态。')],related:['/products/','/collapsible-cups/','/custom-coasters/','/contact/']
 })
];

export const core={
 '/':{title:pair('Silicone & plastic processing for custom drinkware','围绕定制杯项目的硅胶与塑胶加工'),intro:pair('Explore custom cups, LED drinkware and bar accessories by model. The factory operator is 深圳市宝源丰精密加工有限公司; product and order requirements are reviewed for the selected project.','按型号选择定制杯、LED 酒具和配件。工厂主体为深圳市宝源丰精密加工有限公司，产品与订单要求按所选项目确认。'),links:['/custom-plastic-cups/','/custom-silicone-cups/','/custom-led-drinkware/','/factory/'],capabilities:true},
 '/custom-plastic-cups/':{title:pair('Custom plastic cups with logo: choose the right format','定制 Logo 塑料杯：按器型选款'),intro:pair('Compare custom stadium cups, frosted plastic cups, plastic tumblers and stemware using the recorded material and serving capacity. For bulk plastic cups with logo, specify the cup, lid or straw, artwork and quantities per design.','根据已记录材料与使用容量比较体育场杯、磨砂塑料杯、随行杯和高脚杯。批量 Logo 定制需说明杯型、杯盖或吸管、图稿及每版数量。'),links:['/custom-plastic-cups/#stadium-cups','/custom-plastic-cups/#frosted-cups','/screen-printing/','/uv-printing/'],faqs:[question('How do I choose plastic cups with lids and straws?','怎样选带盖和吸管的塑料杯？','Use the exact model and component references. Nominal capacity alone does not establish lid or straw fit. Confirm the chosen components and packing in the specification.','使用具体型号与配件参考，标称容量本身不能证明杯盖或吸管适配；在规格中确认组件和包装。')]},
 '/custom-silicone-cups/':{title:pair('Custom silicone cups: compare shape and use','定制硅胶杯：比较器型与用途'),intro:pair('Compare silicone wine cups, silicone shot glasses and collapsible cups for the intended serving format. For silicone cups with custom logo, review the surface, artwork and required dimensions by model.','按使用方式比较硅胶红酒杯、硅胶烈酒杯与折叠杯。定制 Logo 时应逐型号确认表面、图稿与目标尺寸。'),links:['/collapsible-cups/','/products/silicone-1-5oz-ljb001/','/custom-silicone-cups/#silicone-wine-cups','/free-samples/'],faqs:[question('Which reference can I use for silicone shot glasses?','硅胶烈酒杯可参考哪款？','LJB-001 is the silicone shot-cup reference in the current model library. Review its model page, then confirm the final dimensions, logo and quantities for your project.','当前型号库中 LJB-001 为硅胶烈酒杯参考。可先查看型号页，再确认项目尺寸、Logo 和数量。')]},
 '/led-light-up-cups/':{title:pair('Custom LED cups with logo: plan lighting and production','定制 Logo LED 发光杯：规划灯效与生产'),intro:pair('For custom light up cups and wholesale LED cups, compare vessel shape, lighting, power and branding as one specification. Follow the LED drinkware manufacturing process to prepare the sample and assembly review.','批量定制 LED 发光杯时，应一起比较器型、灯效、供电和品牌装饰。可结合 LED 酒具生产流程准备样品与组装审核需求。'),links:['/custom-led-drinkware/','/custom-led-drinkware/#led-production','/custom-ice-buckets/','/blog/led-drinkware-101/'],faqs:[question('Can LED cups with logo share the same power and lighting?','不同 LED Logo 杯的供电和灯效一样吗？','No common configuration is assumed. State the desired lighting, activation and power preference, then review each selected model. The logo should be checked with the light on and off.','不默认不同型号采用同样配置。请说明灯效、触发和供电偏好，并逐款核对；Logo 也需检查亮灯和熄灯外观。')]},
 '/custom-ice-buckets/':{title:pair('Custom LED ice buckets for branded venue projects','场馆品牌项目定制 LED 冰桶'),intro:pair('Compare custom LED ice buckets by shape and bottle-service requirements. For LED ice buckets with logo, review lighting, access to power or controls, placement and handling alongside the artwork.','按器型与瓶装饮品服务要求比较 LED 冰桶。Logo 定制应结合灯效、供电或开关操作、摆放及搬运方式审核。'),links:['/custom-led-drinkware/','/led-light-up-cups/','/free-samples/','/contact/']},
 '/bar-accessories/':{title:pair('Custom bar accessories: select by function and material','定制酒具配件：按功能与材料选款'),intro:pair('Build a shortlist of custom coasters, bottle openers, wine stoppers, silicone straws, can coolers and bar tools. Match the material and function to each reference rather than treating all accessories as the same product.','杯垫、开瓶器、酒塞、硅胶吸管、罐套与酒吧工具应分别选款，逐个核对材料和功能，避免把不同配件当成同一种产品。'),links:['/custom-coasters/','/custom-bottle-openers/','/bar-accessories/#can-coolers','/bar-accessories/#silicone-straws'],faqs:[question('Are silicone sleeves, neoprene sleeves and foam can coolers interchangeable?','硅胶套、氯丁橡胶套和泡沫罐套可以混为一类吗？','No. They are different material or construction references. Match the intended can, bottle or glass, then confirm the material and decoration for the specific model.','不可以，它们对应不同材料或结构参考。应先核对罐、瓶或杯的适配，再确认具体型号的材料与装饰。')]},
 '/collapsible-cups/':{title:pair('Custom collapsible silicone cups: define your size','定制折叠硅胶杯：先明确目标尺寸'),intro:pair('For custom collapsible cups and folding silicone cups with logo, provide target capacity plus open and folded dimensions. Reference names can include a volume; the final custom specification is agreed for your project.','定制折叠硅胶杯时，请提供目标容量、展开与折叠尺寸。参考名称中可能含容量，最终定制规格按项目确认。'),links:['/custom-silicone-cups/','/free-samples/','/cup-materials-guide/','/contact/']},
 '/custom-coasters/':{title:pair('Custom coasters with logo: size, shape and placement','定制 Logo 杯垫：大小、形状与图案位置'),intro:pair('For custom silicone coasters, acrylic coasters or LED coasters, start with cup-base fit and the required shape. Coaster dimensions are customizable; capacity is not a coaster specification.','定制硅胶、亚克力或 LED 杯垫，应从杯底适配与形状开始。杯垫尺寸可按要求定制，容量不是杯垫参数。'),links:['/bar-accessories/#coasters','/custom-led-drinkware/','/free-samples/','/contact/']},
 '/custom-bottle-openers/':{title:pair('Custom bottle openers and wine openers: match the closure','定制开瓶器与红酒开瓶器：按瓶盖瓶塞选择'),intro:pair('Choose bottle openers by cap or cork, then compare structure, material and logo placement. Electric wine openers KPQ-008 to KPQ-021 use aluminum and ABS components with PD power supply; connector and electrical ratings require model-specific confirmation.','先区分瓶盖与瓶塞，再比较结构、材料和 Logo 位置。KPQ-008 至 KPQ-021 电动红酒开瓶器采用铝制与 ABS 组件、PD 供电；接口与电气参数需逐型号确认。'),links:['/bar-accessories/#bottle-openers','/bar-accessories/#wine-openers','/free-samples/','/contact/']},
 '/factory/':{title:pair('Prepare a factory and production review','准备工厂与生产资料核对'),intro:pair('Request the processing scope, model-specific sample plan and inspection points relevant to your order. A useful review connects the factory operator, selected product and production approval records.','申请与订单相关的加工范围、型号样品方案及检查项目。核对时应把工厂主体、所选产品和生产确认记录联系起来。'),links:['/oem-manufacturer/','/free-samples/','/certificates/','/contact/']},
 '/faq/':{title:pair('Choose a buying guide for your product','按产品选择采购指南'),intro:pair('Use the guides below for custom dimensions, logo placement and lighting decisions. Each guide connects the question to current model references and a project enquiry.','以下指南帮助核对定制尺寸、Logo 位置及灯效，并关联当前型号与项目询价。'),links:['/collapsible-cups/','/custom-coasters/','/custom-bottle-openers/','/custom-led-drinkware/']}
};

const esc=x=>String(x??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const local=(u,zh)=>zh?'/zh'+u:u;
const names={'/products/':pair('All product models','全部产品型号'),'/custom-plastic-cups/':pair('Custom plastic cups','定制塑料杯'),'/custom-silicone-cups/':pair('Custom silicone cups','定制硅胶杯'),'/led-light-up-cups/':pair('Custom LED cups','定制 LED 发光杯'),'/custom-ice-buckets/':pair('Custom LED ice buckets','定制 LED 冰桶'),'/bar-accessories/':pair('Custom bar accessories','定制酒具配件'),'/custom-led-drinkware/':pair('LED customization & production','LED 定制与生产流程'),'/collapsible-cups/':pair('Custom collapsible cups','定制折叠杯'),'/custom-coasters/':pair('Custom coasters with logo','定制 Logo 杯垫'),'/custom-bottle-openers/':pair('Custom bottle & wine openers','定制瓶盖与红酒开瓶器'),'/factory/':pair('Factory & processing scope','工厂与加工范围'),'/oem-manufacturer/':pair('OEM & ODM planning','OEM／ODM 规划'),'/free-samples/':pair('Sample & logo review','样品与 Logo 审核'),'/rush-production/':pair('Arrival-date review','到货日评估'),'/low-moq-custom-cups/':pair('Small-batch order review','小批量订单评估'),'/wholesale/':pair('Wholesale project quotes','批量项目报价'),'/certificates/':pair('Project documentation','项目文件'),'/faq/':pair('Buying FAQ','采购问答'),'/contact/':pair('Prepare a project enquiry','准备项目询价'),'/screen-printing/':pair('Screen printing','丝印'),'/uv-printing/':pair('UV printing','UV 印刷'),'/heat-transfer-printing/':pair('Heat transfer','热转印'),'/distributor-program/':pair('Distributor enquiries','经销采购'),'/wedding-cups/':pair('Wedding drinkware','婚礼杯具'),'/cup-materials-guide/':pair('Cup materials guide','杯具材料指南'),'/blog/led-drinkware-101/':pair('LED model selection guide','LED 型号选型指南')};
export function label(u,zh){const base=u.split('#')[0],id=u.split('#')[1];return (names[base]?.[zh?'zh':'en']||pages.find(p=>p.route===base)?.title[zh?'zh':'en']||base.split('/').filter(Boolean).join(' ').replaceAll('-',' '))+(id?' · '+id.replaceAll('-',' '):'');}
function linksHtml(urls,zh){return urls.map(u=>`<a href="${esc(local(u,zh))}">${esc(label(u,zh))} <span aria-hidden="true">↗</span></a>`).join('');}
function faqsHtml(qs,zh){return `<div class="opt-faq">${qs.map(q=>`<details><summary>${esc(q.q[zh?'zh':'en'])}</summary><p>${esc(q.a[zh?'zh':'en'])}</p></details>`).join('')}</div>`;}
export function pageHtml(p,zh,products){const l=zh?'zh':'en',models=p.models.map(sku=>products.find(p=>p.sku===sku)).filter(Boolean),img=models[0];return `<article class="opt-page"><header class="container-site opt-hero"><div><nav class="ec-library-breadcrumb" aria-label="${zh?'页面导航':'Breadcrumb'}"><a href="${local('/',zh)}">${zh?'首页':'Home'}</a> / ${esc(p.title[l])}</nav><p class="buyer-kicker">${esc(p.kicker[l])}</p><h1>${esc(p.title[l])}</h1><p class="opt-lead">${esc(p.lead[l])}</p><div class="opt-actions"><a class="ec-b2b-button" href="${local('/contact/',zh)}?models=${encodeURIComponent(p.title[l])}">${zh?'准备我的项目需求':'Prepare my project brief'} ↗</a><a href="#opt-comparison">${zh?'查看确认清单':'View the comparison checklist'} ↓</a></div></div><figure><img src="${esc(img.image)}" alt="${esc(img.name)}" width="700" height="700" fetchpriority="high"><figcaption>${esc(img.sku)} · ${zh?'AI 图案预览，图案与配置按确认样为准':'AI artwork preview · artwork and configuration by approval'}</figcaption></figure></header><div class="container-site opt-body"><section class="opt-answer"><h2>${zh?'采购要点':'A practical starting point'}</h2><p>${esc(p.lead[l])}</p></section><section id="opt-comparison"><p class="buyer-kicker">${zh?'型号 · 图稿 · 订单':'MODEL / ARTWORK / ORDER'}</p><h2>${zh?'先把比较条件说清楚。':'Make the comparison specific.'}</h2><div class="opt-table"><table><caption>${zh?'项目确认清单':'Project review checklist'}</caption><thead><tr><th scope="col">${zh?'核对内容':'Review area'}</th><th scope="col">${zh?'需要确认':'What to agree'}</th></tr></thead><tbody>${p.rows.map(([a,b])=>`<tr><th scope="row">${esc(a[l])}</th><td>${esc(b[l])}</td></tr>`).join('')}</tbody></table></div></section><div class="opt-editorial">${p.sections.map((sec,i)=>`<section><span class="opt-step">0${i+1}</span><h2>${esc(sec.title[l])}</h2><p>${esc(sec.text[l])}</p></section>`).join('')}</div><section><p class="buyer-kicker">CUSTOMBYF / ${zh?'对应型号':'MODEL REFERENCES'}</p><h2>${zh?'从真实型号开始讨论。':'Start with a model reference.'}</h2><div class="opt-models">${models.map(m=>`<a href="${esc(local(m.route,zh))}"><img src="${esc(m.image)}" alt="${esc(m.name)}" loading="lazy" width="350" height="350"><span>${esc(m.sku)}</span><h3>${esc(zh?m.zhName:m.name)}</h3><p>${esc(m.material||'')} · ${zh?'AI 图案预览 · 查看型号与定制需求':'AI artwork preview · View model & customization'} ↗</p></a>`).join('')}</div></section><section><p class="buyer-kicker">${zh?'采购问答':'BUYER QUESTIONS'}</p><h2>${zh?'下单前，把问题说清楚。':'Questions before an order.'}</h2>${faqsHtml(p.faqs,zh)}</section><nav class="opt-related" aria-label="${zh?'相关采购指南':'Related buying guides'}">${linksHtml(p.related,zh)}</nav><section class="opt-next"><h2>${zh?'让下一步更具体。':'Make the next step specific.'}</h2><p>${zh?'提供型号、数量、用途、图稿、包装与目的地。在联系页填写需求并上传图稿，提交后查看接收状态。':'Bring the model, quantity, use, artwork, packing and destination. Submit the brief and artwork on the contact page, then check the receiving status.'}</p><a class="ec-b2b-button" href="${local('/contact/',zh)}?models=${encodeURIComponent(p.title[l])}">${zh?'准备项目询价':'Prepare a project enquiry'} ↗</a><p class="opt-updated">${zh?'内容更新：2026-10-24':'Updated: 2026-10-24'}</p></section></div></article>`;}
export function coreHtml(route,zh){const c=core[route];if(!c)return'';const l=zh?'zh':'en';return `<section class="opt-core container-site"${c.capabilities?' id="capabilities"':''}><p class="buyer-kicker">${zh?'选型 · 定制 · 确认':'SELECT / CUSTOMIZE / APPROVE'}</p><h2>${esc(c.title[l])}</h2><p>${esc(c.intro[l])}</p><nav class="opt-related" aria-label="${zh?'相关选型入口':'Related model and process guides'}">${linksHtml(c.links,zh)}</nav>${c.capabilities?`<div class="opt-capabilities">${linksHtml(['/screen-printing/','/uv-printing/','/laser-engraving/','/heat-transfer-printing/','/custom-led-drinkware/','/color-changing-ink/'],zh)}</div>`:''}${c.faqs?faqsHtml(c.faqs,zh):''}</section>`;}
export function schemas(p,zh){const l=zh?'zh':'en',url='https://www.evercup.com'+local(p.route,zh);return[{'@context':'https://schema.org','@type':p.route.startsWith('/blog/')?'Article':'WebPage','@id':url+'#webpage',url,name:p.title[l],headline:p.title[l],description:p.lead[l],inLanguage:zh?'zh-CN':'en',dateModified:'2026-10-24',isPartOf:{'@type':'WebSite',url:'https://www.evercup.com/',name:'EVERCUP'},...(p.route.startsWith('/blog/')?{author:{'@type':'Organization',name:'EVERCUP'}}:{})},{'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:zh?'首页':'Home',item:'https://www.evercup.com'+local('/',zh)},{'@type':'ListItem',position:2,name:p.title[l],item:url}]},{'@context':'https://schema.org','@type':'FAQPage',mainEntity:p.faqs.map(q=>({'@type':'Question',name:q.q[l],acceptedAnswer:{'@type':'Answer',text:q.a[l]}}))}];}
